=head2 Google::Cloud::Sql::V1beta4::CloudSqlResources::ImportContext

Database instance import context.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

Path to the import file in Cloud Storage, in the form
`gs://bucketName/fileName`. Compressed gzip files (.gz) are supported
when `fileType` is `SQL`. The instance must have
write permissions to the bucket and read access to the file.

=item * C<< $msg->database() >> / C<< $msg->database($value) >>

Type: C<String>

The target database for the import. If `fileType` is `SQL`, this field
is required only if the import file does not specify a database, and is
overridden by any database specification in the import file. For entire
instance parallel import operations, the database is overridden by the
database name stored in subdirectory name. If
`fileType` is `CSV`, one database must be specified.

=item * C<< $msg->kind() >> / C<< $msg->kind($value) >>

Type: C<String>

This is always `sql#importContext`.

=item * C<< $msg->file_type() >> / C<< $msg->file_type($value) >>

Type: C<Enum> (L<Google::Cloud::Sql::V1beta4::SqlFileType>)

The file type for the specified uri.
*  `SQL`: The file contains SQL statements.
*  `CSV`: The file contains CSV data.
*  `BAK`: The file contains backup data for a SQL Server instance.

=item * C<< $msg->csv_import_options() >> / C<< $msg->csv_import_options($value) >>

Type: C<Message> (L<Google::Cloud::Sql::V1beta4::CloudSqlResources::ImportContext::SqlCsvImportOptions>)

Options for importing data as CSV.

=item * C<< $msg->import_user() >> / C<< $msg->import_user($value) >>

Type: C<String>

The PostgreSQL user for this import operation. PostgreSQL instances only.

=item * C<< $msg->bak_import_options() >> / C<< $msg->bak_import_options($value) >>

Type: C<Message> (L<Google::Cloud::Sql::V1beta4::CloudSqlResources::ImportContext::SqlBakImportOptions>)

Import parameters specific to SQL Server .BAK files

=item * C<< $msg->sql_import_options() >> / C<< $msg->sql_import_options($value) >>

Type: C<Message> (L<Google::Cloud::Sql::V1beta4::CloudSqlResources::ImportContext::SqlImportOptions>)

Optional. Options for importing data from SQL statements.

=item * C<< $msg->tde_import_options() >> / C<< $msg->tde_import_options($value) >>

Type: C<Message> (L<Google::Cloud::Sql::V1beta4::CloudSqlResources::ImportContext::SqlTdeImportOptions>)

Optional. Import parameters specific to SQL Server .TDE files
Import parameters specific to SQL Server TDE certificates

=back

